function updateCustomScroll(){const max=Math.max(0,editor.scrollHeight-editor.clientHeight),trackH=scrollTrack.clientHeight,ratio=Math.min(1,editor.clientHeight/Math.max(1,editor.scrollHeight)),thumbH=Math.max(46,trackH*ratio),top=max?editor.scrollTop/max*(trackH-thumbH):0;scrollThumb.style.height=thumbH+'px';scrollThumb.style.transform=`translateY(${top}px)`;customScroll.style.visibility=max>1?'visible':'hidden'}editor.addEventListener('scroll',updateCustomScroll);document.getElementById('scrollUp').onclick=()=>editor.scrollBy({top:-180,behavior:'smooth'});document.getElementById('scrollDown').onclick=()=>editor.scrollBy({top:180,behavior:'smooth'});scrollTrack.onclick=e=>{if(e.target===scrollThumb)return;const r=scrollTrack.getBoundingClientRect(),p=(e.clientY-r.top)/r.height;editor.scrollTop=p*(editor.scrollHeight-editor.clientHeight)};scrollThumb.onmousedown=e=>{e.preventDefault();thumbDrag={startY:e.clientY,startScroll:editor.scrollTop};scrollThumb.classList.add('dragging')};window.addEventListener('mousemove',e=>{if(!thumbDrag)return;const max=Math.max(1,editor.scrollHeight-editor.clientHeight),travel=Math.max(1,scrollTrack.clientHeight-scrollThumb.offsetHeight);editor.scrollTop=thumbDrag.startScroll+(e.clientY-thumbDrag.startY)*max/travel});window.addEventListener('mouseup',()=>{thumbDrag=null;scrollThumb.classList.remove('dragging')});window.addEventListener('resize',updateCustomScroll);
function renderProject(){const p=state.Project;editor.innerHTML=`<div class='section-title'><h2>项目归属</h2><span>随方案自动保存</span></div><div class='card'><div class='grid'>${input('项目名称',p.ProjectName,'Project.ProjectName',1,'text',true)}${input('子项目名称',p.SubprojectName,'Project.SubprojectName',1,'text',true)}${input('楼栋编号',p.BuildingNumber,'Project.BuildingNumber',1,'text')}${input('楼梯编号',p.StairNumber,'Project.StairNumber',1,'text')}${input('图名',p.Name,'Project.Name',1,'text',true)}<div class='field'><label>最低层标高 ${lock('BaseElevationLocked','正常情况下锁定；解锁后可手动修改')}</label><input type='number' value='${p.BaseElevation??0}' step='10' data-path='Project.BaseElevation' ${state.BaseElevationLocked?'disabled':''}></div></div></div><div class='card'><b>方案保存说明</b><p style='font-size:12px;color:#667085;line-height:1.7'>点击“保存参数”会把完整楼梯方案保存在本机。下次输入 LTDY 时自动恢复。</p></div>`}
