function storeyMetrics(s,f){const total=s.Flights.reduce((a,x)=>a+n(x.RiserCount),0),h=total? n(s.Height)/total:0,fh=h*n(f.RiserCount),run=n(f.TreadDepth)*Math.max(0,n(f.RiserCount)-1),ok=h>=150&&h<=175;return{h,fh,run,ok}}function averageStoreyPlatforms(si){const s=state.Project.Storeys[si],floors=Object.fromEntries(state.Project.Floors.map(x=>[x.Id,x])),items=[floors[s.LowerFloorId],...s.Landings,floors[s.UpperFloorId]].filter(Boolean),avg=items.reduce((a,x)=>a+n(x.PlatformWidth),0)/Math.max(1,items.length);items.forEach(x=>{x.PlatformWidth=avg;x.PlatformWidthLocked=true});applyStairwellConstraints();post('preview');render(false)}function renderStoreys(){editor.innerHTML=`<div class='section-title'><h2>楼层与逐跑参数</h2><div class='section-tools'><span>构件旁锁可单独解除关联</span><button class='mini' id='addBasement'>+ 地下层</button><button class='mini' id='addStorey'>+ 地上层</button></div></div>`+state.Project.Storeys.map((s,si)=>`<details class='storey' data-storey='${si}' ${si===currentStorey?'open':''}><summary><span class='summary-title'>${esc(s.Name)}</span><span class='summary-meta'>${s.Height} mm · ${s.Flights.length} 跑 · ${s.Flights.reduce((a,f)=>a+n(f.RiserCount),0)} 级</span><button class='mini' data-average-platforms='${si}'>两边平均</button><button class='mini' data-plan-preview='${si}'>平面预览</button><button class='mini danger' data-delete-storey='${si}'>删除</button></summary><div class='storey-body'><div class='grid' style='margin-top:10px'>${input('层高',s.Height,`Project.Storeys.${si}.Height`)}${input('本层总级数',s.TotalRiserCount??s.Flights.reduce((a,f)=>a+n(f.RiserCount),0),`Project.Storeys.${si}.TotalRiserCount`,1)}${input('层编号',s.Id,`Project.Storeys.${si}.Id`,1,'text',true)}</div><div class='subhead'><span>梯段（踏步宽按本层联动）</span><span><button class='lock ${s.StairwellConstraintLocked?'on':'off'}' data-storey-constraint='${si}' title='仅约束本层'>${s.StairwellConstraintLocked?'🔒':'🔓'}</button>按楼梯井约束本层 <button class='mini' data-add-flight='${si}'>+ 一跑</button></span></div>${s.StairwellCo