function levelName(index){const b=n(state.Project.BasementStoreyCount??0),level=index<b?index-b:index-b+1;return level<0?`负${chinese(-level)}层`:`${chinese(level)}层`}function chinese(v){return['零','一','二','三','四','五','六','七','八','九','十'][v]??String(v)}function renameLevels(){state.Project.Storeys.forEach((s,i)=>s.Name=levelName(i));state.Project.Floors.forEach((f,i)=>f.Name=levelName(i)+'楼板')}function normalizeProject(){const p=state.Project,c=p.Construction;if(!p.BasementStoreyCount)p.BasementStoreyCount=p.Storeys.filter((s,i)=>i===0&&String(s.Id).includes('B')).length;if(!c.StairwellWidth)c.StairwellWidth=2500;if(!c.StairwellDepth)c.StairwellDepth=4640;if(!c.Wall)c.Wall={Enabled:true,Thickness:200};c.Wall.Enabled=true;if(p.SchemaVersion<2)p.Storeys.forEach(s=>s.StairwellConstraintLocked=true);if(p.SchemaVersion<3)p.Storeys.forEach(s=>s.TotalRiserCount=s.TotalRiserCount||s.Flights.reduce((a,f)=>a+n(f.RiserCount),0));if(p.SchemaVersion<4){p.Floors.forEach(f=>f.DirectionLinked=true);p.Storeys.forEach(s=>{s.DirectionLinked=true;s.Flights.forEach(f=>{f.DirectionLinked=true;f.SectionRepresentationLinked=true});s.Landings.forEach(x=>x.DirectionLinked=true)})}if(p.SchemaVersion<5){p.Storeys.forEach(s=>s.TreadDepthLinked=true);p.SchemaVersion=5}if(state.BaseElevationLocked===undefined)state.BaseElevationLocked=true;if(state.ConstructionLinked===undefined)state.ConstructionLinked=true;renameLevels();applyStairwellConstraints()}
