document.querySelectorAll('.tab').forEach(x=>x.onclick=()=>{tab=x.dataset.tab;render()});window.chrome.webview.addEventListener('message',e=>{if(e.data.type==='state'){state=e.data.state;normalizeProject();tab='project';currentStorey=0;viewState=null;render();post('preview');return}if(e.data.type==='measured'){state=e.data.state;normalizeProject();render(false);const notice=document.getElementById('notice');notice.textContent='已从 CAD 框选回填参数';setTimeout(()=>notice.textContent='',2500);post('preview');return}if(e.data.type!=='preview')return;document.getElementById('svgHost').innerHTML=e.data.svg;const svg=document.getElementById('sectionSvg');if(svg){const initial=svg.getAttribute('viewBox');svg.dataset.initial=initial;if(!viewState){const a=initial.split(' ').map(n);viewState={x:a[0],y:a[1],w:a[2],h:a[3]}}applyView()}bindSvg();const s=document.getElementById('summary');s.textContent=e.data.summary;s.className=e.data.success?'':'error'});installCadNavigation();normalizeProject();render();post('preview');
const renderGlobalWithHatches=renderGlobal;renderGlobal=function(){renderGlobalWithHatches();const c=state.Project.Construction,box=document.createElement('div');box.className='card';box.innerHTML=`<div class='group-title'>剖切加粗与填充</div><div class='grid'>${input('结构填充图案',c.SectionHatch.PatternName,'Project.Construction.SectionHatch.PatternName',1,'text')}${input('结构填充比例',c.SectionHatch.PatternScale,'Project.Construction.SectionHatch.PatternScale')}${input('墙体填充图案',c.WallHatch.PatternName,'Project.Construction.WallHatch.PatternName',1,'text')}${input('墙体填充比例',c.WallHatch.PatternScale,'Project.Construction.WallHatch.PatternScale')}</div><div class='ok'>剖切边界内偏移 0.2×比例，加粗线宽 0.4×比例；双击构件可直接修改对应填充。</div>`;editor.appendChild(box)};
