const openQuickEditorWithHatch=openQuickEditor;openQuickEditor=function(id){const c=findComponent(id),supports=id==='WALL'||c?.kind==='flight'||c?.kind==='landing'||c?.kind==='floor';if(!supports){openQuickEditorWithHatch(id);return}const h=id==='WALL'?state.Project.Construction.WallHatch:state.Project.Construction.SectionHatch,original=JSON.parse(JSON.stringify(h));openQuickEditorWithHatch(id);const modal=document.querySelector('.modal'),note=modal?.querySelector('.modal-note');if(!modal)return;const card=document.createElement('div');card.className='card';card.style.cssText='display:grid;gap:10px;padding:12px;margin-top:12px;background:#fff8e8';card.innerHTML=`<b>${id==='WALL'?'墙体':'结构'}剖切填充</b><label><input type='checkbox' data-hatch-enabled ${h.Enabled?'checked':''}> 启用填充</label><div class='grid'><div class='field'><label>填充图案</label><input type='text' data-hatch-pattern value='${esc(h.PatternName)}'></div><div class='field'><label>填充比例</label><input type='number' min='0.001' step='0.1' data-hatch-scale value='${h.PatternScale}'></div></div><div class='modal-note'>这里是附加设置；上方原有构件参数仍按原逻辑修改。</div>`;modal.querySelector('.modal-body').insertBefore(card,note);card.querySelector('[data-hatch-enabled]').onchange=e=>{h.Enabled=e.target.checked;post('preview')};card.querySelector('[data-hatch-pattern]').oninput=e=>{h.PatternName=e.target.value||'ANSI31';post('preview')};card.querySelector('[data-hatch-scale]').oninput=e=>{h.PatternScale=Math.max(.001,n(e.target.value));post('preview')};modal.querySelectorAll('[data-close]').forEach(x=>x.addEventListener('click',()=>{Object.keys(original).forEach(k=>h[k]=original[k]);post('preview')}))};
const hatchPatternOptions=[['WL_RC_CONCRETE_V2','钢筋混凝土 · 插件素材'],['WL_RC_CONCRETE','钢筋混凝土 · 旧版'],['ANSI311','ANSI311 · 45°单斜线'],['ANSI31','ANSI31 · 45°单斜线'],['ANSI32','ANSI32 · 双斜线'],['ANSI33','ANSI33 · 三斜线'],['ANSI34','ANSI34 · 交叉线'],['ANSI35','ANSI35 · 交叉密线'],['ANSI36','ANSI36 · 网格线'],['AR-CONC','AR-CONC · 混凝土'],['AR-BRSTD','AR-BRSTD · 标准砖'],['SOLID','SOLID · 实体填充']];function hatchPreviewStyle(name){if(name==='SOLID')return'background:#8d969f';if(name==='WL_RC_CONCRETE'||name==='WL_RC_CONCRETE_V2')return'background-color:#fff;background-image:radial-gradient(#78828c 1.2px,transparent 1.4px),repeating-linear-gradient(45deg,transparent 0,transparent 12px,#9aa2aa 13px,#9aa2aa 14px);background-size:17px 15px,auto';if(name==='AR-BRSTD')return'background-color:#fff;background-image:linear-gradient(#78828c 1px,transparent 1px),linear-gradient(90deg,#78828c 1px,transparent 1px);background-size:24px 12px';if(name==='AR-CONC')return'background-color:#fff;background-image:radial-gradient(#78828c 1.4px,transparent 1.5px);background-size:11px 9px';const cross=['ANSI34','ANSI35','ANSI36'].includes(name),dense=['ANSI33','ANSI35','ANSI36'].includes(name)?6:10;return`background-color:#fff;background-image:repeating-linear-gradient(45deg,transparent 0,transparent ${dense-1}px,#78828c ${dense}px,#78828c ${dense+1}px)${cross?',repeating-linear-gradient(-45deg,transparent 0,transparent '+(dense-1)+'px,#a4abb2 '+dense+'px,#a4abb2 '+(dense+1)+'px)':''}`}function hatchSelectorHtml(value,kind){return`<select data-hatch-choice='${kind}'>${hatchPatternOptions.map(x=>`<option value='${x[0]}' ${x[0]===value?'selected':''}>${x[1]}</option>`).join('')}</select><div data-hatch-preview='${kind}' style='height:58px;margin-top:6px;border:1px solid #aeb8c4;border-radius:4px;${hatchPreviewStyle(value)}'></div>`}function bindHatchSelector(root,kind,h){const select=root.querySelector(`[data-hatch-choice='${kind}']`),preview=root.querySelector(`[data-hatch-preview='${kind}']`);if(!select)return;select.onchange=()=>{h.PatternName=select.value;preview.style.cssText=`height:58px;margin-top:6px;border:1px solid #aeb8c4;border-radius:4px;${hatchPreviewStyle(h.PatternName)}`;post('preview')}}
const renderGlobalWithPatternPreview=renderGlobal;renderGlobal=function(){renderGlobalWithPatternPreview();const c=state.Project.Construction,structureInput=editor.querySelector(`[data-path='Project.Construction.SectionHatch.PatternName']`),wallInput=editor.querySelector(`[data-path='Project.Construction.WallHatch.PatternName']`);if(structureInput){const field=structureInput.closest('.field');field.innerHTML=`<label>结构填充图案</label>${hatchSelectorHtml(c.SectionHatch.PatternName,'structure')}`;bindHatchSelector(field,'structure',c.SectionHatch)}if(wallInput){const field=wallInput.closest('.field');field.innerHTML=`<label>墙体填充图案</label>${hatchSelectorHtml(c.WallHatch.PatternName,'wall')}`;bindHatchSelector(field,'wall',c.WallHatch)}};
const openQuickEditorWithPatternPreview=openQuickEditor;openQuickEditor=function(id){openQuickEditorWithPatternPreview(id);const modal=document.querySelector('.modal'),input=modal?.querySelector('[data-hatch-pattern]');if(!input)return;const h=id==='WALL'?state.Project.Construction.WallHatch:state.Project.Construction.SectionHatch,field=input.closest('.field'),kind=id==='WALL'?'quick-wall':'quick-structure';field.innerHTML=`<label>填充图案</label>${hatchSelectorHtml(h.PatternName,kind)}`;bindHatchSelector(field,kind,h)};
</script></body></html>";
